import{_ as i,o as e,c as t,a3 as r}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"串联结构的误差传播","description":"","frontmatter":{"translationSource":{"title":"串联结构的误差传播","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=LbIb8qSMuIb0YhWSlQiP1F","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/error-propagation-in-serial-structures"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/error-propagation-in-serial-structures"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/error-propagation-in-serial-structures"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/error-propagation-in-serial-structures"}]]},"headers":[],"relativePath":"zh/error-propagation-in-serial-structures.md","filePath":"zh/page-LbIb8qSMuIb0YhWSlQiP1F.md"}'),_={name:"zh/error-propagation-in-serial-structures.md"};function l(p,a,o,d,n,s){return e(),t("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="串联结构的误差传播" aria-hidden="true"></span><h1 id="串联结构的误差传播" tabindex="-1">串联结构的误差传播 <a class="header-anchor" href="#串联结构的误差传播" aria-label="Permalink to &quot;串联结构的误差传播&quot;">​</a></h1><blockquote><p>源页面 ID：<code>LbIb8qSMuIb0YhWSlQiP1F</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=LbIb8qSMuIb0YhWSlQiP1F" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>定理：若序列 a 与 b 串联（b 的输出作为 a 的输入触发），生成序列 c，则波动幅度满足：</p><p>M_dev^c &lt;= M_dev^a + T_ideal^a * M_dev^b</p><p>证明：</p><p>设 a 的1的位置序列为 {t_i^a}{i=1}^{K_a}，理想间隔 T_ideal^a = L_a/K_a；</p><p>b 的1的位置序列为 {t_i^b}{i=1}^{K_b}，理想间隔 T_ideal^b = L_b/K_b。</p><p>串联后 c 的第 i 个1位于 a 的第 t_i^b 个1处：</p><p>t_i^c = t_{t_i^b}^a</p><p>且 K_c = K_b，T_ideal^c = T_ideal^a * T_ideal^b。</p><p>c 的第 i 次输出误差：</p><p>E_c(i) = t_i^c - i * T_ideal^c</p><p>= t_{t_i^b}^a - i * T_ideal^a * T_ideal^b</p><p>= [E_a(t_i^b) + t_i^b * T_ideal^a] - i * T_ideal^a * T_ideal^b</p><p>= E_a(t_i^b) + (t_i^b - i * T_ideal^b) * T_ideal^a</p><p>= E_a(t_i^b) + E_b(i) * T_ideal^a</p><p>因此：</p><p>max_i E_c(i) &lt;= max_j E_a(j) + T_ideal^a * max_i E_b(i)</p><p>min_i E_c(i) &gt;= min_j E_a(j) + T_ideal^a * min_i E_b(i)</p><p>两式相减得：</p><p>M_dev^c &lt;= M_dev^a + T_ideal^a * M_dev^b</p><p>证明由 jnk 完成，无人审阅正确性，由 jnk 进行了标准名词化</p></div>',1)])])}const h=i(_,[["render",l]]);export{b as __pageData,h as default};
